def is_available(timeout: float = 3.0) -> tuple[bool, str]:
    # llama-server (디폴트 worker, ADR-199 v4)
    try:
        import urllib.request
        req = urllib.request.Request("http://localhost:8080/v1/models")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            if resp.status == 200:
                return True, "llama-server ready (port 8080)"
    except Exception:
        pass
    # fallback: LM Studio
    try:
        provider = LmStudioProvider(...)
        if provider.ping():
            return True, f"LM Studio {LM_HOST} ready (fallback)"
    except Exception as e:
        return False, f"both unreachable; lm_studio={str(e)[:60]}"
    return False, "both llama-server and LM Studio unreachable"
